//! Word lists and suffix rules backing `Inflector`.
//!
//! All comparisons are byte-exact and case-sensitive, matching the original: the
//! library never case-folds before consulting a list, so `sheep` is uncountable
//! while `Sheep` is not, and `mice` reads as a plural while `Mice` does not.

/// Words the original treats as having no distinct plural form.
///
/// `pluralize` returns these unchanged and `is_plural` rejects them outright,
/// which is what keeps `police` singular even though it ends in the `lice`
/// plural suffix below.
pub const UNCOUNTABLE: [&[u8]; 10] = [
    b"equipment",
    b"information",
    b"rice",
    b"money",
    b"species",
    b"series",
    b"fish",
    b"sheep",
    b"jeans",
    b"police",
];

/// Suffix that reads as singular even though it ends in `s`, so `news` and
/// `renews` are not plurals while `News` (capital `N`) is.
pub const SINGULAR_S_SUFFIX: &[u8] = b"news";

/// Plural suffixes that do not end in `s`.
///
/// Matched as unanchored suffixes, which is why `Police` and `malice` are
/// reported as plural: only the trailing `lice` has to match, not the whole word.
pub const PLURAL_SUFFIXES: [&[u8]; 6] = [
    b"mice", b"lice", // (m|l)ice -> ouse
    b"ta", b"ia", //     [ti]a    -> um
    b"octopi", b"viri", // (octop|vir)i -> us
];

/// Plural whose match is anchored to the whole word: `oxen` only, never `boxen`
/// or `oxenx`.
pub const PLURAL_EXACT: [&[u8]; 1] = [b"oxen"];

pub fn is_uncountable(word: &[u8]) -> bool {
    UNCOUNTABLE.contains(&word)
}

