//! The `inflection::Inflector` API surface, reimplemented over raw bytes.

use crate::inflection::rules;

/// Mirrors the `std::out_of_range` that `std::string::substr` throws when the
/// requested position is past the end of the string.
///
/// `demodulize` can genuinely reach this: it skips two bytes past the *last*
/// single colon, so a trailing `::` leaves it pointing one byte past the end.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OutOfRange {
    pub pos: usize,
    pub size: usize,
}

impl std::fmt::Display for OutOfRange {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "basic_string::substr: __pos (which is {}) > this->size() (which is {})",
            self.pos, self.size
        )
    }
}

pub struct Inflector;

impl Inflector {
    /// Present for parity with the C++ entry point; the rule tables here are
    /// `const`, so there is nothing to build at run time.
    pub fn initialize() {}

    /// Appends `s`, except for uncountable words and the empty string.
    ///
    /// Deliberately naive, like the original: `box` -> `boxs`, `city` -> `citys`,
    /// `child` -> `childs`. There is no irregular table and no `es`/`ies` handling.
    pub fn pluralize(word: &[u8]) -> Vec<u8> {
        if word.is_empty() || rules::is_uncountable(word) {
            return word.to_vec();
        }
        let mut out = Vec::with_capacity(word.len() + 1);
        out.extend_from_slice(word);
        out.push(b's');
        out
    }

    /// Splits on `_` and upper-cases the first byte of every segment but the
    /// first, leaving the rest of each segment alone.
    ///
    /// The leading segment keeps its original case, so this yields lower camel
    /// case for lower-case input (`hello_world` -> `helloWorld`) and upper camel
    /// case for capitalised input (`Hello_World` -> `HelloWorld`). Acronyms
    /// survive intact: `HTTP_request` -> `HTTPRequest`.
    pub fn camelize(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        for (i, segment) in word.split(|&b| b == b'_').enumerate() {
            match segment.split_first() {
                Some((&first, rest)) if i > 0 => {
                    out.push(first.to_ascii_uppercase());
                    out.extend_from_slice(rest);
                }
                _ => out.extend_from_slice(segment),
            }
        }
        out
    }

    /// Lower-cases each ASCII upper-case byte, inserting `_` before every one
    /// that is not the first byte of the string.
    ///
    /// No acronym grouping and no separator rewriting, so `HTTPRequest` becomes
    /// `h_t_t_p_request` and `Foo::Bar` becomes `foo::_bar`.
    pub fn underscore(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        for (i, &b) in word.iter().enumerate() {
            if b.is_ascii_uppercase() {
                if i > 0 {
                    out.push(b'_');
                }
                out.push(b.to_ascii_lowercase());
            } else {
                out.push(b);
            }
        }
        out
    }

    /// Reports whether the word looks like a plural form.
    ///
    /// A trailing lower-case `s` is the general signal; the suffix lists cover
    /// the plurals that do not end in `s` (`mice`, `data`, `octopi`, `oxen`).
    /// Note this is a pure suffix test, not a round trip through a singularizer:
    /// `class`, `bus` and `status` all report plural.
    pub fn is_plural(word: &[u8]) -> bool {
        if word.is_empty() || rules::is_uncountable(word) {
            return false;
        }
        if word.ends_with(rules::SINGULAR_S_SUFFIX) {
            return false;
        }
        if rules::PLURAL_EXACT.contains(&word) {
            return true;
        }
        if rules::PLURAL_SUFFIXES.iter().any(|s| word.ends_with(s)) {
            return true;
        }
        word.last() == Some(&b's')
    }

    /// The exact complement of [`Inflector::is_plural`].
    pub fn is_singular(word: &[u8]) -> bool {
        !Self::is_plural(word)
    }

    /// Strips the leading namespace qualification.
    ///
    /// Reproduces the original's off-by-one: it locates the *last* `:` and then
    /// skips two bytes, so `Module::cat` yields `at` rather than `cat`, and a
    /// string ending in `::` walks one byte past the end and throws.
    pub fn demodulize(path: &[u8]) -> Result<Vec<u8>, OutOfRange> {
        let Some(last_colon) = path.iter().rposition(|&b| b == b':') else {
            return Ok(path.to_vec());
        };
        let pos = last_colon + 2;
        if pos > path.len() {
            return Err(OutOfRange {
                pos,
                size: path.len(),
            });
        }
        Ok(path[pos..].to_vec())
    }
}

