//! Rust port of `tests/test15.cpp`.
//!
//! Usage: `test15 [word1 [word2 ...]]` — the first five arguments are inflected,
//! and `underscore` is additionally applied to every even-numbered one.

mod inflection;

use inflection::inflector::OutOfRange;
use inflection::Inflector;
use std::io::Write;

/// `argv` as raw byte strings.
///
/// `std::env::args()` panics on arguments that are not valid UTF-8, and even for
/// valid input the C++ original slices `std::string` mid-codepoint, so the whole
/// program has to speak bytes to stay byte-for-byte compatible.
fn argv() -> Vec<Vec<u8>> {
    std::env::args_os()
        .map(|arg| {
            #[cfg(unix)]
            {
                use std::os::unix::ffi::OsStrExt;
                arg.as_bytes().to_vec()
            }
            #[cfg(not(unix))]
            {
                arg.to_string_lossy().into_owned().into_bytes()
            }
        })
        .collect()
}

fn write_line(out: &mut impl Write, bytes: &[u8]) {
    out.write_all(bytes).expect("write to stdout");
    out.write_all(b"\n").expect("write to stdout");
}

/// Reproduces an uncaught C++ exception: the `terminate` diagnostic on stderr
/// followed by `SIGABRT`, matching the original's exit status of 134.
fn terminate(out: &mut impl Write, err: OutOfRange) -> ! {
    let _ = out.flush();
    eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
    eprintln!("  what():  {}", err);
    let _ = std::io::stderr().flush();
    std::process::abort();
}

fn main() {
    Inflector::initialize();

    let args = argv();
    let argc = args.len();

    // 15 API calls
    let mut results: Vec<Vec<u8>> = Vec::new();

    let mut i = 1;
    while i < argc && i <= 5 {
        let word = &args[i];

        results.push(Inflector::pluralize(word));
        results.push(Inflector::camelize(word));
        if i % 2 == 0 {
            results.push(Inflector::underscore(word));
        }

        i += 1;
    }

    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    // Output all results
    for result in &results {
        write_line(&mut out, result);
    }

    // Extra API calls to bring the total to 15
    if argc > 1 {
        let word = &args[1];

        write_line(&mut out, bool_str(Inflector::is_plural(word)));
        write_line(&mut out, bool_str(Inflector::is_singular(word)));

        let mut qualified = b"Module::".to_vec();
        qualified.extend_from_slice(word);
        match Inflector::demodulize(&qualified) {
            Ok(name) => write_line(&mut out, &name),
            Err(err) => terminate(&mut out, err),
        }
    }
}

/// `std::cout << bool` without `boolalpha`.
fn bool_str(value: bool) -> &'static [u8] {
    if value {
        b"1"
    } else {
        b"0"
    }
}

