78	    let mut corpus: Vec<Vec<u8>> = Vec::new();
79	    for w in WORDS {
80	        for v in case_variants(w) {
81	            corpus.push(v.into_bytes());
82	        }
83	    }
84	    for p in PREFIXES {
85	        for s in SUFFIXES {
86	            for v in case_variants(&format!("{p}{s}")) {
87	                corpus.push(v.into_bytes());
88	            }
89	        }
90	    }
91	
92	    // Random ASCII strings over a separator-heavy alphabet.
93	    let alphabet: &[u8] = b"abcSXZ_-:./ sae19";
94	    let mut rng = Rng(0x1234_5678_9abc_def1);
95	    for _ in 0..6000 {
96	        let len = rng.below(9);
97	        let s: Vec<u8> = (0..len).map(|_| alphabet[rng.below(alphabet.len())]).collect();
98	        corpus.push(s);
99	    }
100	    // Random raw bytes (no NUL: it cannot survive argv).
101	    for _ in 0..1200 {
102	        let len = 1 + rng.below(7);
103	        let s: Vec<u8> = (0..len).map(|_| 1 + (rng.below(255) as u8)).collect();
104	        corpus.push(s);
105	    }
106	
107	    corpus.sort();
108	    corpus.dedup();
109	    corpus
110	}
