112	fn run(bin: &str, args: &[Vec<u8>]) -> (Vec<u8>, Vec<u8>, Option<i32>) {
113	    let out = Command::new(bin)
114	        .args(args.iter().map(|a| OsStr::from_bytes(a)))
115	        .output()
116	        .expect("spawn");
117	    (out.stdout, out.stderr, out.status.code())
118	}
119	
120	fn show(args: &[Vec<u8>]) -> String {
121	    args.iter()
122	        .map(|a| format!("{:?}", String::from_utf8_lossy(a)))
123	        .collect::<Vec<_>>()
124	        .join(" ")
125	}
