127	fn main() {
128	    let corpus = build_corpus();
129	    eprintln!("corpus: {} entries", corpus.len());
130	
131	    let mut cases: Vec<Vec<Vec<u8>>> = corpus.iter().map(|w| vec![w.clone()]).collect();
132	
133	    // Multi-argument cases: exercise the even-index `underscore` calls and the
134	    // `i <= 5` truncation.
135	    let mut rng = Rng(0x00c0_ffee_1234_5677);
136	    for _ in 0..9000 {
137	        let n = 2 + rng.below(6);
138	        cases.push(
139	            (0..n)
140	                .map(|_| corpus[rng.below(corpus.len())].clone())
141	                .collect(),
142	        );
143	    }
144	    cases.push(vec![]); // no arguments at all
145	
146	    let total = cases.len();
147	    let mut fails = 0;
148	    for (n, args) in cases.iter().enumerate() {
149	        let a = run(CPP, args);
150	        let b = run(RUST, args);
151	        if a != b {
152	            fails += 1;
153	            if fails <= 15 {
154	                println!("MISMATCH [{}]", show(args));
155	                println!("  cpp  stdout={:?}", String::from_utf8_lossy(&a.0));
156	                println!("  rust stdout={:?}", String::from_utf8_lossy(&b.0));
157	                if a.1 != b.1 {
158	                    println!("  cpp  stderr={:?}", String::from_utf8_lossy(&a.1));
159	                    println!("  rust stderr={:?}", String::from_utf8_lossy(&b.1));
160	                }
161	                if a.2 != b.2 {
162	                    println!("  exit cpp={:?} rust={:?}", a.2, b.2);
163	                }
164	            }
165	        }
166	        if n % 2000 == 0 {
167	            eprintln!("  {n}/{total}");
168	        }
169	    }
170	    println!("\n{} cases, {} mismatches", total, fails);
171	    if fails > 0 {
172	        std::process::exit(1);
173	    }
174	}
